const intentLabels={en:{name:'Trip name',from:'From',to:'To',start:'Earliest departure',end:'Latest return',budget:'Budget (AUD)',passengers:'Travellers',baggage:'Baggage (kg/person)',transit:'Maximum transit (hours)',seat:'Seat'},vi:{name:'Tên chuyến đi',from:'Điểm đi',to:'Điểm đến',start:'Ngày đi sớm nhất',end:'Ngày về muộn nhất',budget:'Ngân sách (AUD)',passengers:'Số khách',baggage:'Hành lý (kg/người)',transit:'Nối chuyến tối đa (giờ)',seat:'Chỗ ngồi'}} as const;
